// Field model

#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub enum Section {
    Lora,
    Device,
    Position,
    Power,
    Network,
    Display,
    Bluetooth,
    Security,
    Mqtt,
    Serial,
    Telemetry,
    CannedMessage,
    ExternalNotification,
    StoreForward,
    RangeTest,
}

impl Section {
    /// Whether this section belongs to the module config family.
    pub fn is_module(self) -> bool {
        matches!(
            self,
            Section::Mqtt
                | Section::Serial
                | Section::Telemetry
                | Section::CannedMessage
                | Section::ExternalNotification
                | Section::StoreForward
                | Section::RangeTest
        )
    }
}

#[derive(Debug, Clone, Copy)]
pub enum FieldKind {
    Bool,
    U32 {
        min: u32,
        max: u32,
    },
    I32 {
        min: i32,
        max: i32,
    },
    F32,
    Text,
    Password,
    /// A choice among `(label, value)` pairs.
    Enum(&'static [(&'static str, i32)]),
}

#[derive(Debug, Clone, Copy)]
pub struct Field {
    pub key: &'static str,
    pub label: &'static str,
    pub help: &'static str,
    pub kind: FieldKind,
}

#[derive(Debug, Clone, Copy)]
pub struct SectionSpec {
    pub section: Section,
    pub title: &'static str,
    pub description: &'static str,
    pub fields: &'static [Field],
}

const fn text(key: &'static str, label: &'static str, help: &'static str) -> Field {
    Field {
        key,
        label,
        help,
        kind: FieldKind::Text,
    }
}
const fn password(key: &'static str, label: &'static str, help: &'static str) -> Field {
    Field {
        key,
        label,
        help,
        kind: FieldKind::Password,
    }
}
const fn boolean(key: &'static str, label: &'static str, help: &'static str) -> Field {
    Field {
        key,
        label,
        help,
        kind: FieldKind::Bool,
    }
}
const fn u32f(
    key: &'static str,
    label: &'static str,
    help: &'static str,
    min: u32,
    max: u32,
) -> Field {
    Field {
        key,
        label,
        help,
        kind: FieldKind::U32 { min, max },
    }
}
const fn i32f(
    key: &'static str,
    label: &'static str,
    help: &'static str,
    min: i32,
    max: i32,
) -> Field {
    Field {
        key,
        label,
        help,
        kind: FieldKind::I32 { min, max },
    }
}
const fn f32f(key: &'static str, label: &'static str, help: &'static str) -> Field {
    Field {
        key,
        label,
        help,
        kind: FieldKind::F32,
    }
}
const fn enumerate(
    key: &'static str,
    label: &'static str,
    help: &'static str,
    options: &'static [(&'static str, i32)],
) -> Field {
    Field {
        key,
        label,
        help,
        kind: FieldKind::Enum(options),
    }
}

// Generated read/write per config type

macro_rules! io_read {
    ($v:expr, text) => {
        $v.clone()
    };
    ($v:expr, $kind:ident) => {
        $v.to_string()
    };
}

macro_rules! io_parse {
    ($v:expr, text) => {
        Ok::<_, String>($v.to_string())
    };
    ($v:expr, bool) => {
        Ok::<_, String>($v.eq_ignore_ascii_case("true"))
    };
    ($v:expr, u32) => {
        $v.trim().parse::<u32>().map_err(|e| e.to_string())
    };
    ($v:expr, i32) => {
        $v.trim().parse::<i32>().map_err(|e| e.to_string())
    };
    ($v:expr, f32) => {
        $v.trim().parse::<f32>().map_err(|e| e.to_string())
    };
}

macro_rules! config_io {
    ($read:ident, $write:ident, $ty:ty, { $( $key:literal => $field:ident : $kind:ident ),* $(,)? }) => {
        fn $read(c: &$ty, key: &str) -> String {
            match key {
                $( $key => io_read!(c.$field, $kind), )*
                _ => String::new(),
            }
        }
        fn $write(c: &mut $ty, key: &str, value: &str) -> Result<(), String> {
            match key {
                $( $key => {
                    c.$field = io_parse!(value, $kind)?;
                    Ok(())
                } )*
                _ => Err(format!("unknown field: {key}")),
            }
        }
    };
}

