// SectionValue: one concrete config behind a common enum

#[derive(Debug, Clone)]
pub enum SectionValue {
    Device(DeviceConfig),
    Position(PositionConfig),
    Power(PowerConfig),
    Network(NetworkConfig),
    Display(DisplayConfig),
    Lora(LoRaConfig),
    Bluetooth(BluetoothConfig),
    Security(SecurityConfig),
    Mqtt(MqttConfig),
    Serial(SerialConfig),
    Telemetry(TelemetryConfig),
    CannedMessage(CannedMessageConfig),
    ExternalNotification(ExternalNotificationConfig),
    StoreForward(StoreForwardConfig),
    RangeTest(RangeTestConfig),
}

impl SectionValue {
    pub fn default_for(section: Section) -> Self {
        match section {
            Section::Device => SectionValue::Device(DeviceConfig::default()),
            Section::Position => SectionValue::Position(PositionConfig::default()),
            Section::Power => SectionValue::Power(PowerConfig::default()),
            Section::Network => SectionValue::Network(NetworkConfig::default()),
            Section::Display => SectionValue::Display(DisplayConfig::default()),
            Section::Lora => SectionValue::Lora(LoRaConfig::default()),
            Section::Bluetooth => SectionValue::Bluetooth(BluetoothConfig::default()),
            Section::Security => SectionValue::Security(SecurityConfig::default()),
            Section::Mqtt => SectionValue::Mqtt(MqttConfig::default()),
            Section::Serial => SectionValue::Serial(SerialConfig::default()),
            Section::Telemetry => SectionValue::Telemetry(TelemetryConfig::default()),
            Section::CannedMessage => SectionValue::CannedMessage(CannedMessageConfig::default()),
            Section::ExternalNotification => {
                SectionValue::ExternalNotification(ExternalNotificationConfig::default())
            }
            Section::StoreForward => SectionValue::StoreForward(StoreForwardConfig::default()),
            Section::RangeTest => SectionValue::RangeTest(RangeTestConfig::default()),
        }
    }

    /// Extract the relevant section from a downloaded `Config`.
    pub fn from_config(section: Section, config: &Config) -> Option<Self> {
        Some(match (section, config.payload_variant.as_ref()?) {
            (Section::Device, config::PayloadVariant::Device(c)) => SectionValue::Device(c.clone()),
            (Section::Position, config::PayloadVariant::Position(c)) => SectionValue::Position(*c),
            (Section::Power, config::PayloadVariant::Power(c)) => SectionValue::Power(*c),
            (Section::Network, config::PayloadVariant::Network(c)) => {
                SectionValue::Network(c.clone())
            }
            (Section::Display, config::PayloadVariant::Display(c)) => SectionValue::Display(*c),
            (Section::Lora, config::PayloadVariant::Lora(c)) => SectionValue::Lora(c.clone()),
            (Section::Bluetooth, config::PayloadVariant::Bluetooth(c)) => {
                SectionValue::Bluetooth(*c)
            }
            (Section::Security, config::PayloadVariant::Security(c)) => {
                SectionValue::Security(c.clone())
            }
            _ => return None,
        })
    }

    /// Extract the relevant section from a downloaded `ModuleConfig`.
    pub fn from_module_config(section: Section, config: &ModuleConfig) -> Option<Self> {
        Some(match (section, config.payload_variant.as_ref()?) {
            (Section::Mqtt, module_config::PayloadVariant::Mqtt(c)) => {
                SectionValue::Mqtt(c.clone())
            }
            (Section::Serial, module_config::PayloadVariant::Serial(c)) => SectionValue::Serial(*c),
            (Section::Telemetry, module_config::PayloadVariant::Telemetry(c)) => {
                SectionValue::Telemetry(*c)
            }
            (Section::CannedMessage, module_config::PayloadVariant::CannedMessage(c)) => {
                SectionValue::CannedMessage(c.clone())
            }
            (
                Section::ExternalNotification,
                module_config::PayloadVariant::ExternalNotification(c),
            ) => SectionValue::ExternalNotification(*c),
            (Section::StoreForward, module_config::PayloadVariant::StoreForward(c)) => {
                SectionValue::StoreForward(*c)
            }
            (Section::RangeTest, module_config::PayloadVariant::RangeTest(c)) => {
                SectionValue::RangeTest(*c)
            }
            _ => return None,
        })
    }

    /// Wrap as a `Config` (device sections only).
    pub fn to_config(&self) -> Option<Config> {
        let payload_variant = match self {
            SectionValue::Device(c) => config::PayloadVariant::Device(c.clone()),
            SectionValue::Position(c) => config::PayloadVariant::Position(*c),
            SectionValue::Power(c) => config::PayloadVariant::Power(*c),
            SectionValue::Network(c) => config::PayloadVariant::Network(c.clone()),
            SectionValue::Display(c) => config::PayloadVariant::Display(*c),
            SectionValue::Lora(c) => config::PayloadVariant::Lora(c.clone()),
            SectionValue::Bluetooth(c) => config::PayloadVariant::Bluetooth(*c),
            SectionValue::Security(c) => config::PayloadVariant::Security(c.clone()),
            _ => return None,
        };
        Some(Config {
            payload_variant: Some(payload_variant),
        })
    }

    /// Wrap as a `ModuleConfig` (module sections only).
    pub fn to_module_config(&self) -> Option<ModuleConfig> {
        let payload_variant = match self {
            SectionValue::Mqtt(c) => module_config::PayloadVariant::Mqtt(c.clone()),
            SectionValue::Serial(c) => module_config::PayloadVariant::Serial(*c),
            SectionValue::Telemetry(c) => module_config::PayloadVariant::Telemetry(*c),
            SectionValue::CannedMessage(c) => {
                module_config::PayloadVariant::CannedMessage(c.clone())
            }
            SectionValue::ExternalNotification(c) => {
                module_config::PayloadVariant::ExternalNotification(*c)
            }
            SectionValue::StoreForward(c) => module_config::PayloadVariant::StoreForward(*c),
            SectionValue::RangeTest(c) => module_config::PayloadVariant::RangeTest(*c),
            _ => return None,
        };
        Some(ModuleConfig {
            payload_variant: Some(payload_variant),
        })
    }

    pub fn read(&self, key: &str) -> String {
        match self {
            SectionValue::Device(c) => read_device(c, key),
            SectionValue::Position(c) => read_position(c, key),
            SectionValue::Power(c) => read_power(c, key),
            SectionValue::Network(c) => read_network(c, key),
            SectionValue::Display(c) => read_display(c, key),
            SectionValue::Lora(c) => read_lora(c, key),
            SectionValue::Bluetooth(c) => read_bluetooth(c, key),
            SectionValue::Security(c) => read_security(c, key),
            SectionValue::Mqtt(c) => read_mqtt(c, key),
            SectionValue::Serial(c) => read_serial(c, key),
            SectionValue::Telemetry(c) => read_telemetry(c, key),
            SectionValue::CannedMessage(c) => read_canned(c, key),
            SectionValue::ExternalNotification(c) => read_extnotif(c, key),
            SectionValue::StoreForward(c) => read_storeforward(c, key),
            SectionValue::RangeTest(c) => read_rangetest(c, key),
        }
    }

    pub fn write(&mut self, key: &str, value: &str) -> Result<(), String> {
        match self {
            SectionValue::Device(c) => write_device(c, key, value),
            SectionValue::Position(c) => write_position(c, key, value),
            SectionValue::Power(c) => write_power(c, key, value),
            SectionValue::Network(c) => write_network(c, key, value),
            SectionValue::Display(c) => write_display(c, key, value),
            SectionValue::Lora(c) => write_lora(c, key, value),
            SectionValue::Bluetooth(c) => write_bluetooth(c, key, value),
            SectionValue::Security(c) => write_security(c, key, value),
            SectionValue::Mqtt(c) => write_mqtt(c, key, value),
            SectionValue::Serial(c) => write_serial(c, key, value),
            SectionValue::Telemetry(c) => write_telemetry(c, key, value),
            SectionValue::CannedMessage(c) => write_canned(c, key, value),
            SectionValue::ExternalNotification(c) => write_extnotif(c, key, value),
            SectionValue::StoreForward(c) => write_storeforward(c, key, value),
            SectionValue::RangeTest(c) => write_rangetest(c, key, value),
        }
    }
}

