/// Every section, in the order they appear in Settings.
pub fn all_specs() -> &'static [&'static SectionSpec] {
    ALL_SPECS
}

pub fn spec(section: Section) -> &'static SectionSpec {
    all_specs()
        .iter()
        .find(|s| s.section == section)
        .expect("every Section has a spec")
}

// Editors

/// An open config-section editor.
#[derive(Debug, Clone)]
pub struct Editor {
    pub spec: &'static SectionSpec,
    pub original: SectionValue,
    pub values: HashMap<String, String>,
    pub error: Option<String>,
}

impl Editor {
    pub fn new(section: Section, current: Option<SectionValue>) -> Self {
        let spec = spec(section);
        let original = current.unwrap_or_else(|| SectionValue::default_for(section));
        let values = spec
            .fields
            .iter()
            .map(|field| (field.key.to_string(), original.read(field.key)))
            .collect();
        Self {
            spec,
            original,
            values,
            error: None,
        }
    }

    pub fn value(&self, key: &str) -> &str {
        self.values.get(key).map(String::as_str).unwrap_or("")
    }

    pub fn set(&mut self, key: &str, value: String) {
        self.values.insert(key.to_string(), value);
        self.error = None;
    }

    /// Apply the edited values to a fresh copy of the original config,
    /// validating numeric ranges on the way.
    pub fn build(&self) -> Result<SectionValue, String> {
        let mut value = self.original.clone();
        for field in self.spec.fields {
            let raw = self.value(field.key);
            match field.kind {
                FieldKind::U32 { min, max } => {
                    let parsed: u32 = raw
                        .trim()
                        .parse()
                        .map_err(|_| format!("{} must be a whole number", field.label))?;
                    if parsed < min || parsed > max {
                        return Err(format!("{} must be between {min} and {max}", field.label));
                    }
                }
                FieldKind::I32 { min, max } => {
                    let parsed: i32 = raw
                        .trim()
                        .parse()
                        .map_err(|_| format!("{} must be a whole number", field.label))?;
                    if parsed < min || parsed > max {
                        return Err(format!("{} must be between {min} and {max}", field.label));
                    }
                }
                _ => {}
            }
            value.write(field.key, raw)?;
        }
        Ok(value)
    }
}

/// An open channel editor.
#[derive(Debug, Clone)]
pub struct ChannelEditor {
    pub index: i32,
    pub original: Channel,
    pub values: HashMap<String, String>,
    pub error: Option<String>,
}

impl ChannelEditor {
    pub fn new(index: i32, original: Channel) -> Self {
        let settings = original.settings.clone().unwrap_or_default();
        let mut values = HashMap::new();
        values.insert("name".to_string(), settings.name.clone());
        values.insert("psk".to_string(), bytes_to_hex(&settings.psk));
        values.insert("role".to_string(), original.role.to_string());
        values.insert(
            "uplink_enabled".to_string(),
            settings.uplink_enabled.to_string(),
        );
        values.insert(
            "downlink_enabled".to_string(),
            settings.downlink_enabled.to_string(),
        );
        Self {
            index,
            original,
            values,
            error: None,
        }
    }

    pub fn value(&self, key: &str) -> &str {
        self.values.get(key).map(String::as_str).unwrap_or("")
    }

    pub fn set(&mut self, key: &str, value: String) {
        self.values.insert(key.to_string(), value);
        self.error = None;
    }

    pub fn build(&self) -> Result<Channel, String> {
        let mut channel = self.original.clone();
        let settings = channel
            .settings
            .get_or_insert_with(ChannelSettings::default);
        settings.name = self.value("name").to_string();
        settings.psk = hex_to_bytes(self.value("psk"))?;
        settings.uplink_enabled = self.value("uplink_enabled").eq_ignore_ascii_case("true");
        settings.downlink_enabled = self.value("downlink_enabled").eq_ignore_ascii_case("true");
        // Channel 0 is always primary; others may be disabled/secondary.
        channel.role = if self.index == 0 {
            meshtastic_protobufs::meshtastic::channel::Role::Primary as i32
        } else {
            self.value("role").trim().parse().unwrap_or(channel.role)
        };
        Ok(channel)
    }
}

/// Render a byte slice as lowercase hex.
pub fn bytes_to_hex(bytes: &[u8]) -> String {
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push_str(&format!("{byte:02x}"));
    }
    out
}

/// Parse a hex string (even length) into bytes.
pub fn hex_to_bytes(text: &str) -> Result<Vec<u8>, String> {
    let text = text.trim();
    if text.is_empty() {
        return Ok(Vec::new());
    }
    if text.len() % 2 != 0 {
        return Err("hex value must have an even number of digits".to_string());
    }
    (0..text.len())
        .step_by(2)
        .map(|i| {
            u8::from_str_radix(&text[i..i + 2], 16)
                .map_err(|_| format!("invalid hex: {}", &text[i..i + 2]))
        })
        .collect()
}

/// Generate a random 256-bit channel key as hex.
pub fn random_channel_key() -> String {
    let key: [u8; 32] = rand::random();
    bytes_to_hex(&key)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn lora_round_trips_through_editor() {
        let mut lora = LoRaConfig {
            region: 1,
            hop_limit: 3,
            ..Default::default()
        };
        lora.tx_power = 27;
        let value = SectionValue::Lora(lora);
        let mut editor = Editor::new(Section::Lora, Some(value));
        assert_eq!(editor.value("region"), "1");
        editor.set("region", "3".into());
        editor.set("hop_limit", "5".into());
        editor.set("tx_enabled", "true".into());
        let built = editor.build().unwrap();
        let config = built.to_config().unwrap();
        match config.payload_variant {
            Some(config::PayloadVariant::Lora(l)) => {
                assert_eq!(l.region, 3);
                assert_eq!(l.hop_limit, 5);
                assert!(l.tx_enabled);
            }
            _ => panic!("expected lora"),
        }
    }

    #[test]
    fn from_config_extracts_and_fills_editor() {
        let config = Config {
            payload_variant: Some(config::PayloadVariant::Lora(LoRaConfig {
                region: 3,
                hop_limit: 5,
                tx_power: 20,
                ..Default::default()
            })),
        };
        let value = SectionValue::from_config(Section::Lora, &config).unwrap();
        let editor = Editor::new(Section::Lora, Some(value));
        assert_eq!(editor.value("region"), "3");
        assert_eq!(editor.value("hop_limit"), "5");
        assert_eq!(editor.value("tx_power"), "20");
        assert_eq!(editor.value("tx_enabled"), "false");

        // Module sections come from ModuleConfig.
        let module = ModuleConfig {
            payload_variant: Some(module_config::PayloadVariant::Telemetry(TelemetryConfig {
                device_update_interval: 900,
                ..Default::default()
            })),
        };
        let value = SectionValue::from_module_config(Section::Telemetry, &module).unwrap();
        let editor = Editor::new(Section::Telemetry, Some(value));
        assert_eq!(editor.value("device_update_interval"), "900");
        assert!(SectionValue::from_config(Section::Telemetry, &config).is_none());
    }

    #[test]
    fn invalid_number_is_reported() {
        let editor = Editor::new(Section::Lora, None);
        let mut editor = editor;
        editor.set("hop_limit", "not-a-number".into());
        assert!(editor.build().is_err());
    }

    #[test]
    fn module_config_wrapping() {
        let value = SectionValue::Mqtt(MqttConfig {
            enabled: true,
            address: "mqtt.local".into(),
            ..Default::default()
        });
        let module = value.to_module_config().unwrap();
        assert!(matches!(
            module.payload_variant,
            Some(module_config::PayloadVariant::Mqtt(_))
        ));
        assert!(value.to_config().is_none());
    }

    #[test]
    fn channel_editor_builds_psk() {
        let channel = Channel {
            index: 2,
            role: 2,
            settings: Some(ChannelSettings {
                name: "Team".into(),
                psk: vec![0xab, 0xcd],
                ..Default::default()
            }),
        };
        let mut editor = ChannelEditor::new(2, channel);
        assert_eq!(editor.value("psk"), "abcd");
        editor.set("psk", "0102".into());
        editor.set("name", "Renamed".into());
        let built = editor.build().unwrap();
        assert_eq!(built.settings.unwrap().psk, vec![0x01, 0x02]);
        assert_eq!(built.role, 2);
    }

    #[test]
    fn hex_helpers() {
        assert_eq!(bytes_to_hex(&[0x00, 0xff, 0x10]), "00ff10");
        assert_eq!(hex_to_bytes("00ff10").unwrap(), vec![0x00, 0xff, 0x10]);
        assert!(hex_to_bytes("abc").is_err());
        assert!(hex_to_bytes("zz").is_err());
    }
}
